pragma solidity >=0.8.0;

contract IntDivCaptureBeforeCount {
    int8 public min8;
    int16 public min16;
    int64 public min64;
    int8 public r8;
    int16 public r16;
    int64 public r64;
    uint256 public count;

    constructor() {
        min8 = type(int8).min;
        min16 = type(int16).min;
        min64 = type(int64).min;
    }

    function div8() public returns (int8) {
        int8 r = min8 / int8(-1);
        r8 = r;
        count++;
        return r;
    }

    function div16() public returns (int16) {
        int16 r = min16 / int16(-1);
        r16 = r;
        count++;
        return r;
    }

    function div64() public returns (int64) {
        int64 r = min64 / int64(-1);
        r64 = r;
        count++;
        return r;
    }
}
